	@Test
	void unknownAndWrappedSourcesKeepTheirOwnViewCapability() {
		NativeLmdbQuerySource unknown = new LmdbNativePackedParallelQuoteOwnershipTest.SnapshotSource();
		NativeLmdbQuerySource disabled = mock(NativeLmdbQuerySource.class);
		when(disabled.idSpace()).thenReturn(unknown.idSpace());
		when(disabled.hasStatementsInSource()).thenReturn(true);
		when(disabled.mayHaveWildcardViews()).thenReturn(false);
		assertThat(unknown.predicateDomainCardinality()).isEmpty();
		assertThat(unknown.mayHaveWildcardViews()).as("absent metadata is not a disabled-view proof").isTrue();
		assertThat(new SyntheticValueSource(unknown, PlanValueCatalog.EMPTY).mayHaveWildcardViews()).isTrue();
		assertThat(new SyntheticValueSource(disabled, PlanValueCatalog.EMPTY).mayHaveWildcardViews()).isFalse();
		assertThat(CompositeNativeLmdbQuerySource.combine(List.of(disabled, disabled)).mayHaveWildcardViews())
				.isFalse();
		assertThat(CompositeNativeLmdbQuerySource.combine(List.of(disabled, unknown)).mayHaveWildcardViews())
				.as("an unknown constituent cannot inherit another source's disabled capability")
				.isTrue();
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void parsedOrderedWildcardQueryNamesItsServingPhysicalRoute(boolean adjacencyEnabled) throws Exception {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacencyEnabled)
				.setDirectAdjacencyMode(adjacencyEnabled ? DirectAdjacencyMode.PREFER : DirectAdjacencyMode.DISABLED)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL)
				.setDirectAdjacencyMaxBytes(LmdbStoreConfig.DIRECT_ADJACENCY_MIN_EXPLICIT_BYTES));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				ValueFactory values = connection.getValueFactory();
				IRI first = values.createIRI(FIRST);
				IRI second = values.createIRI(SECOND);
				connection.begin();
				for (int root = 1; root <= 16; root++) {
					IRI subject = values.createIRI("urn:ordered-wildcard:" + root);
					connection.add(subject, first, values.createIRI("urn:ordered-wildcard:" + (root + 100)));
					connection.add(subject, second, values.createIRI("urn:ordered-wildcard:" + (root + 200)));
				}
				connection.commit();
			}
			if (adjacencyEnabled) {
				assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			}
			List<String> expected = IntStream.rangeClosed(1, 16)
					.boxed()
					.flatMap(root -> List.of(
							row(root, FIRST, root + 100), row(root, SECOND, root + 200)).stream())
					.toList();
			List<BindingSet> ordinary;
			set("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
			try (SailRepositoryConnection connection = repository.getConnection()) {
				ordinary = QueryResults.asList(connection.prepareTupleQuery(QUERY).evaluate());
				assertThat(canonical(ordinary)).containsExactlyInAnyOrderElementsOf(expected);
			} finally {
				set("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
			}
			try (SailRepositoryConnection connection = repository.getConnection()) {
				List<BindingSet> results = QueryResults.asList(connection.prepareTupleQuery(QUERY).evaluate());
				assertThat(canonical(results)).as("the native result bag must match the ordinary evaluator")
						.containsExactlyInAnyOrderElementsOf(canonical(ordinary));
			}
			String actualRoute = adjacencyEnabled ? LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD_INTERPRETED
					: LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED;
			List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
			List<LmdbNativeDecisionTestAccess.Captured> candidates = new ArrayList<>();
			long variableLoweringsBefore = LmdbNativeKernelLowering.VARIABLE_PREDICATE_LOWERINGS.get();
			String explanation;
			try (SailRepositoryConnection connection = repository.getConnection();
					AutoCloseable decisions = LmdbNativeDecisionTestAccess.capture(candidates);
					AutoCloseable capture = LmdbNativeDecisionTestAccess.captureSelections(selected)) {
				explanation = connection.prepareTupleQuery(QUERY).explain(Explanation.Level.Executed).toString();
			}
			assertThat(explanation).as("prove the actual physical route before asserting its candidate identity")
					.contains("nativeExecutionPath=" + actualRoute);
			assertThat(selected.stream().filter(selection -> "ORDER".equals(selection.point())).toList())
					.singleElement()
					.satisfies(selection -> assertThat(selection.id()).isEqualTo(actualRoute));
			if (!adjacencyEnabled) {
				assertSoftly(softly -> {
					softly.assertThat(candidates.stream()
							.filter(candidate -> LmdbNativeDecisionPoint.ORDER.label()
									.equals(candidate.decisionPoint()))
							.filter(LmdbNativeDecisionTestAccess.Captured::admitted)
							.map(LmdbNativeDecisionTestAccess.Captured::id)
							.toList())
							.as("a source with adjacency disabled cannot admit a wildcard-view candidate")
							.doesNotContain(LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD,
									LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD_INTERPRETED);
					softly.assertThat(
							LmdbNativeKernelLowering.VARIABLE_PREDICATE_LOWERINGS.get() - variableLoweringsBefore)
							.as("the ordinary peer must start from its scan family without constructing wildcard-view kernels")
							.isZero();
				});
			}
		} finally {
			repository.shutDown();
		}
	}

	private static List<String> canonical(List<BindingSet> rows) {
		return rows.stream()
				.map(result -> result.getValue("s").stringValue() + "|"
						+ result.getValue("a").stringValue() + "|" + result.getValue("p").stringValue() + "|"
						+ result.getValue("b").stringValue())
				.toList();
	}

	private static String row(int root, String predicate, int object) {
		return "urn:ordered-wildcard:" + root + "|urn:ordered-wildcard:" + (root + 100) + "|"
				+ predicate + "|urn:ordered-wildcard:" + object;
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}
